import type { ApiTour, Localized } from "./demo-tour-types";
import type { Tour } from "@/types/tour";

/** Демо-туры только для тестов фильтров и поиска: на сайте их больше нет */
export function isApiTour(value: unknown): value is ApiTour {
  if (!value || typeof value !== "object") return false;
  const t = value as Partial<ApiTour>;
  return (
    typeof t.slug === "string" &&
    typeof t.price === "number" &&
    !!t.title &&
    typeof t.title.en === "string" &&
    Array.isArray(t.itinerary)
  );
}

export function localizeTour(raw: ApiTour, locale: Locale): Tour {
  const pick = (value: Localized | undefined) => value?.[locale] || value?.en || "";
  return {
    id: raw._id ?? null,
    slug: raw.slug,
    place: pick(raw.place) || pick(raw.title),
    title: pick(raw.title),
    country: pick(raw.country),
    summary: pick(raw.summary),
    overview: pick(raw.overview),
    region: raw.region,
    coords: raw.coords,
    image: raw.image,
    gallery: raw.gallery ?? [],
    price: raw.price,
    rating: raw.rating,
    reviews: raw.reviews,
    days: raw.days,
    groupSize: raw.groupSize,
    difficulty: raw.difficulty,
    languages: raw.languages ?? [],
    category: raw.category,
    badge: raw.badge ?? null,
    highlights: (raw.highlights ?? []).map((h) => ({ title: pick(h.title), text: pick(h.text), image: h.image })),
    itinerary: (raw.itinerary ?? []).map((s) => ({ day: s.day, title: pick(s.title), text: pick(s.text), coords: s.coords })),
    included: raw.included ?? [],
    excluded: raw.excluded ?? [],
  };
}


